#include <pthread.h>
#include <stdio.h>

static long counter = 0;             // shared - and unprotected on purpose

static void *bump(void *arg) {
    (void)arg;
    for (int i = 0; i < 1000000; i++)
        counter = counter + 1;       // load, add, store: three steps
    return NULL;
}

int main(void) {
    pthread_t t1, t2;
    pthread_create(&t1, NULL, bump, NULL);
    pthread_create(&t2, NULL, bump, NULL);
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);
    printf("%ld\n", counter);        // usually < 2000000, differs per run
    return 0;
}

#include <pthread.h>
#include <stdio.h>

static long counter = 0;
static pthread_mutex_t mtx = PTHREAD_MUTEX_INITIALIZER;

static void *bump(void *arg) {
    (void)arg;
    for (int i = 0; i < 1000000; i++) {
        pthread_mutex_lock(&mtx);
        counter = counter + 1;       // exclusive inside the critical section
        pthread_mutex_unlock(&mtx);
    }
    return NULL;
}

int main(void) {
    pthread_t t1, t2;
    pthread_create(&t1, NULL, bump, NULL);
    pthread_create(&t2, NULL, bump, NULL);
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);
    printf("%ld\n", counter);        // exactly 2000000, every run
    return 0;
}

